using System;using System.IO;using System.Reflection;using UnityEditor;using UnityEngine;using TMPro;using Bokumyaku.Presentation;
public static class BundledFontCheck{
public static object Run(){var g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(!g.SavePath.Contains("ink-qa-"))throw new Exception("Isolated only");var f=Resources.Load<TMP_FontAsset>("BokumyakuFonts/BattleJapanese");int labels=0;foreach(var t in UnityEngine.Object.FindObjectsByType<TextMeshProUGUI>(FindObjectsSortMode.None)){if(t.font!=f)throw new Exception("Unexpected font");foreach(char c in t.text)if(!char.IsControl(c)&&!f.HasCharacter(c))throw new Exception("Missing glyph "+c);labels++;}if(Application.targetFrameRate!=60)throw new Exception("Frame target");SessionState.SetInt("Bokumyaku.ExpectedFrameRate",(int)typeof(BokumyakuGame).GetField("previousFrameRate",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(g));var result=new{labels,font=AssetDatabase.GetAssetPath(f),mode=f.atlasPopulationMode.ToString(),fpsTarget=Application.targetFrameRate};File.WriteAllText(Path.GetFullPath("../docs/evidence/bundled-font-check.json"),Newtonsoft.Json.JsonConvert.SerializeObject(result));ScreenCapture.CaptureScreenshot(Path.GetFullPath("../docs/evidence/bundled-font-battle.png"));return result;}
public static object AfterStop(){if(EditorApplication.isPlaying)throw new Exception("Stop first");bool passed=Application.targetFrameRate==SessionState.GetInt("Bokumyaku.ExpectedFrameRate",-999);var result=new{passed,restored=Application.targetFrameRate};File.WriteAllText(Path.GetFullPath("../docs/evidence/frame-target-restore.json"),Newtonsoft.Json.JsonConvert.SerializeObject(result));if(!passed)throw new Exception("Not restored");return result;}}
